template <typename T>
class Channel {
  std::queue<T> q_; std::mutex m_; std::condition_variable cv_;
 public:
  void send(T v) { { std::lock_guard<std::mutex> g(m_); q_.push(std::move(v)); } cv_.notify_one(); }
  T receive() { std::unique_lock<std::mutex> g(m_);
                cv_.wait(g, [this]{ return !q_.empty(); });
                T v = std::move(q_.front()); q_.pop(); return v; }
};
Channel<Order> orders;      // channel identity == message type
Channel<Invoice> invoices;
